# third storyboard (final, after review pass 3: English polish). Drafts: alt3_script_v0/v1/v2.py
S=[
(1, 4, 'A lovely video', "Inigo Quilez's video is lovely, with many directions to explore.", "``Reply to Inigo Quilez --- youtube.com/shorts/cc-Z\\_igk4Lo''", 'His setup, schematic: a circle, a tilted line that misses it, two orange hidden dots. Credit caption fades in. First person, Carlo.'),
(2, 6, 'The one I chose', 'I chose one: circles acting on circles, with complex numbers everywhere. One closed operation, one invariant.', 'circle $\\star$ circle over $\\mathbb C$ $\\cdot$ one invariant $\\kappa$', 'A mirror circle flips a blue circle into its dashed image.'),
(3, 5, 'His move', 'His move: when the square root goes negative, the intersection points turn complex.', '$\\mathbf p=\\mathbf o-\\mathbf d\\bigl(\\mathbf o\\cdot\\mathbf d\\pm i\\sqrt{|\\Delta|}\\bigr)$', 'His formula, rewritten with $\\sqrt{|\\Delta|}$ (on his screen the orange $i$ is inserted and the radicand left unchanged); orange dots on his line, centred on his point $\\mathbf o$.'),
(4, 6, 'Our slice', 'Our slice: a unit circle and a vertical line, x equals t, sliding without turning.', '$x=t$', 'The vertical line slides left to right; two blue dots ride the circle.'),
(5, 7, 'Not his picture', 'His orange dots hang on his moving point o; ours sit at the foot of the perpendicular. Our version, not his.', 'his: $\\mathbf o\\pm s\\,\\mathbf d$ $\\;|\\;$ ours: foot $\\pm s$', 'Split screen: left his convention, right ours.'),
(6, 6, 'Real, then hidden', "Inside, the points are t, plus or minus a real root. Outside, they're plus or minus i s.", '$(t,\\pm\\sqrt{1-t^2})$ $\\;|\\;$ $(t,\\pm is)$, $s=\\sqrt{t^2-1}$', 'Left $t=0.6$: blue dots. Right $t=1.6$: orange rings, labelled $\\pm is$.'),
(7, 6, 'A hyperbola', 'Drop the i, plot s, and you get a hyperbola: t squared minus s squared equals one.', '$t^2-s^2=1$', 'The orange rings leave a trail: two hyperbola branches beside the blue circle.'),
(8, 7, 'One curve', 'Better: give the imaginary part its own axis. Circle and hyperbola join into one curve, meeting where the line touches.', 'axes $t$, $\\mathrm{Re}\\,y$, $\\mathrm{Im}\\,y$', '3D: all points $(t,y)$ of $x^2+y^2=1$ with $x=t$ real. Then $y^2$ is real, so $y$ is real or purely imaginary: the circle (plane $\\mathrm{Im}\\,y=0$) plus the hyperbola (plane $\\mathrm{Re}\\,y=0$), meeting at $t=\\pm1$. Colour: blue = real, orange = imaginary. Slow orbit.'),
(9, 7, 'Four complex numbers', 'A circle is four numbers: a, b, c, d. Let them be complex; only ratios matter, and lines have a zero.', '$a(x^2+y^2)+bx+cy+d=0$, $[a:b:c:d]\\in\\mathbb P^3(\\mathbb C)$; lines: $a=0$', 'Three real circles and a line, each tagged with its four numbers; the tags turn complex and a common factor $\\lambda$ is crossed out.'),
(10, 6, 'Its Q', "Each circle carries one number, Q. For a real circle it's four times the radius squared.", '$Q=b^2+c^2-4ad$; real circle: $Q/a^2=4r^2$', 'Radius drawn; $Q$ computed.'),
(11, 5, 'The operation', 'The operation: reflect C in L by subtracting just the right multiple of L.', '$C\\star L=C-\\frac{2\\langle C,L\\rangle}{Q(L)}\\,L$', 'Formula slams in over a mirror circle $L$ and blue $C$.'),
(12, 7, 'Familiar, and closed', "For real circles, that's reflection in a line, or inversion in a circle. Circle in, circle out, even over C.", 'line: reflection $\\;|\\;$ circle: inversion $\\;\\Rightarrow\\;$ $C\\star L\\in\\mathbb P^3(\\mathbb C)$', 'Two panels: a circle reflected in a line; a circle and a line inverted in a circle.'),
(13, 6, 'One exception', 'The only forbidden mirrors have Q equal to zero: point-circles, and lines through the circular points.', '$Q(L)=0$: no mirror (point-circles, centre anywhere in $\\mathbb C^2$ or at $\\infty$; lines with $b^2+c^2=0$)', 'A point-circle with a no-entry mark; text: lines with $b^2+c^2=0$.'),
(14, 7, 'Three rules: a kei', 'The rules: a mirror fixes itself, reflecting twice brings you back, and mirrors carry relations along. That makes a kei.', '$L\\star L\\sim L$ (it is $-L$); $(C\\star L)\\star L=C$; $(A\\star B)\\star L=(A\\star L)\\star(B\\star L)$; a kei (Takasaki 1943)', 'Rules type on one per beat; the word kei lands last.'),
(15, 8, 'Always two', 'Where does circle C meet line L? Substituting gives a quadratic with leading term a times Q of L: always two points.', '$a\\,Q(L)\\,u^2+\\dots=0$', 'A circle and a crossing line; the quadratic writes on; two blue dots.'),
(16, 7, 'Through the mirror', 'Reflect C in L: C star L is C minus a multiple of L, so it meets C where L does.', '$C\\star L=C-kL$ $\\Rightarrow$ $C\\cap(C\\star L)=C\\cap L$ (if $k\\neq0$; $k=0$ means $C\\star L=C$)', '$C\\star L$ appears dashed through the same two dots; the family $C-kL$ fans out through them.'),
(17, 8, 'Four, really', 'As curves, two circles meet four times: twice at the circular points I and J, shared by every circle, and twice on our line.', '$2\\cdot2=4$: $I=[1:i:0]$, $J=[1:-i:0]$, and two on $L$', 'Bézout count; two arrows off to infinity labelled $I$, $J$; then $L$ glows between $C$ and $C\\star L$.'),
(18, 7, 'The invariant', 'Chain mirrors and you get the complex Möbius group. One number survives all of it: kappa.', '$\\langle\\text{mirrors}\\rangle=PO(4,\\mathbb C)$; $\\kappa=\\frac{\\langle C,L\\rangle^2}{Q(C)Q(L)}$', 'A circle bounces through three mirrors; then the formula for $\\kappa$, with the same value on both configurations.'),
(19, 5, 'Tangency', 'Kappa equals one exactly when the two points merge: tangency.', '$\\kappa=1\\iff$ tangent', 'Three panels $\\kappa<1$, $=1$, $>1$.'),
(20, 6, 'In our slice', 'In our slice, kappa is just t squared: below one they cross, above one they hide.', '$\\kappa=t^2$', 'Parabola $\\kappa(t)$ with the crossing band.'),
(21, 6, 'Not realness', 'Complex maps keep the two points, tangency and kappa, but not whether the points are real.', 'random $g\\in PO(4,\\mathbb C)$: $\\kappa$ $0.360\\to0.360$; still two points, now with complex coordinates (points on the Möbius quadric, $\\infty$ included)', 'Checklist.'),
(22, 7, 'A complex circle', 'A complex circle splits into two real circles: its real and imaginary parts. Its real points are where they cross.', '$C=C_1+iC_2$; real points of $C$ $=C_1\\cap C_2$', '$C_1$ and $C_2$ drawn; their crossings glow.'),
(23, 6, 'Two or none', 'So it has two real points, one, or none, and a similar test decides.', '$\\langle C_1,C_2\\rangle^2-Q(C_1)Q(C_2)$: $<0$ two, $=0$ one, $>0$ none (whole circle if $C$ is real up to scale)', 'Three panels.'),
(24, 5, 'Nudge the circle', 'Now nudge our unit circle off the reals, and sweep the line again.', '$x^2+y^2+i\\varepsilon x=1$', '3D curves for $\\varepsilon=0.3$, ghost of $\\varepsilon=0$.'),
(25, 6, 'They come apart', 'The junctions come apart: tangency now happens at complex t, so the real sweep never splits.', '$\\kappa(t)=1$ at $t=\\pm0.989-0.15i$', 'Zoom on the gap near $t=1$.'),
(26, 4, 'Two, all the way', 'Two points all the way. No switch, no branching.', '2 points for every real $t$; real only at $t=0$', '3D orbit.'),
(27, 5, 'Hidden is a slice', 'Hidden is just what a real slice does to one symmetric picture.', 'real plane $\\mathrm{Im}\\,y=0$', 'Back to $\\varepsilon=0$; the real plane is shaded.'),
(28, 5, 'Recap', 'One operation, circle star circle. One invariant, kappa, with tangency at one.', '$C\\star L$ $\\cdot$ $\\kappa$ $\\cdot$ $\\kappa=1\\iff$ tangent', 'Recap.'),
(29, 4, 'Always two, over C', 'Always two points, real or not.', '$\\#(C\\cap L)=2$ (with multiplicity; $a\\neq0$, $Q(L)\\neq0$)', 'Recap.'),
(30, 4, 'Thanks', 'Thanks, Inigo, for the spark.', 'reply to @InigoQuilez', 'Final hold.'),
]
if __name__=='__main__':
    T=sum(s[1] for s in S); Wd=sum(len(s[3].split()) for s in S)
    print(len(S),'scenes',T,'s',Wd,'words',round(Wd/T,2),'w/s')
    for s in S:
        r=len(s[3].split())/s[1]
        if r>2.9 or r<1.5: print('PACE',s[0],len(s[3].split()),s[1],round(r,2))
